class Solution {
public:
    bool matchReplacement(std::string s, std::string sub, std::vector<std::vector<char>>& mappings) {
        bool allowed[128][128] = {false};
        for (const auto& m : mappings) allowed[(unsigned char)m[0]][(unsigned char)m[1]] = true;
        int n = s.size(), m = sub.size();
        for (int i = 0; i <= n - m; ++i) {
            bool matched = true;
            for (int j = 0; j < m; ++j) {
                char sc = s[i + j], tc = sub[j];
                if (sc != tc && !allowed[(unsigned char)tc][(unsigned char)sc]) {
                    matched = false;
                    break;
                }
            }
            if (matched) return true;
        }
        return false;
    }
};

class Solution {
    public boolean matchReplacement(String s, String sub, char[][] mappings) {
        boolean[][] allowed = new boolean[128][128];
        for (char[] m : mappings) allowed[m[0]][m[1]] = true;
        int n = s.length(), m = sub.length();
        for (int i = 0; i <= n - m; i++) {
            boolean matched = true;
            for (int j = 0; j < m; j++) {
                char sc = s.charAt(i + j), tc = sub.charAt(j);
                if (sc != tc && !allowed[tc][sc]) {
                    matched = false;
                    break;
                }
            }
            if (matched) return true;
        }
        return false;
    }
}

var matchReplacement = function(s, sub, mappings) {
    const allowed = Array.from({ length: 128 }, () => new Uint8Array(128));
    for (const [u, v] of mappings) {
        allowed[u.charCodeAt(0)][v.charCodeAt(0)] = 1;
    }
    const n = s.length, m = sub.length;
    for (let i = 0; i <= n - m; i++) {
        let matched = true;
        for (let j = 0; j < m; j++) {
            const sc = s.charCodeAt(i + j), tc = sub.charCodeAt(j);
            if (sc !== tc && allowed[tc][sc] !== 1) {
                matched = false;
                break;
            }
        }
        if (matched) return true;
    }
    return false;
};
